const themePalette={"paper":{"id":"paper","paper":"#faf9f5","side":"#f0f1e9","banner":"#e9eddf","ink":"#2b302b","accent":"#e9785d"},"tide":{"id":"tide","paper":"#f4f8fa","side":"#e8f0f4","banner":"#ddeaf2","ink":"#293742","accent":"#3868ac"},"clay":{"id":"clay","paper":"#fbf6ef","side":"#f3eade","banner":"#f0dfce","ink":"#40352d","accent":"#ae503b"},"olive":{"id":"olive","paper":"#f6f8f0","side":"#eaf0df","banner":"#e0e8cf","ink":"#30392b","accent":"#677c3c"},"midnight":{"id":"midnight","paper":"#151b20","side":"#10161b","banner":"#24313a","ink":"#eef2f0","accent":"#fa9077"},"forest":{"id":"forest","paper":"#17221e","side":"#111c18","banner":"#25392f","ink":"#eef5ec","accent":"#a6d2a0"},"espresso":{"id":"espresso","paper":"#211c1a","side":"#191513","banner":"#382c26","ink":"#f7eee5","accent":"#e6a17b"},"slate":{"id":"slate","paper":"#19232b","side":"#121b22","banner":"#293c48","ink":"#eef4f6","accent":"#83c2d7"},"sand":{"id":"sand","paper":"#f8f3ea","side":"#eee5d8","banner":"#e9ddc9","ink":"#3b342e","accent":"#b16d4d"},"rose":{"id":"rose","paper":"#fbf5f4","side":"#f2e7e6","banner":"#efddda","ink":"#403334","accent":"#bd6e72"},"obsidian":{"id":"obsidian","paper":"#101114","side":"#090a0c","banner":"#24262b","ink":"#f3f3f4","accent":"#c4c8d2"},"amethyst":{"id":"amethyst","paper":"#1c1726","side":"#15101e","banner":"#30273f","ink":"#f2ebfa","accent":"#c4a2f0"},"burgundy":{"id":"burgundy","paper":"#24171d","side":"#1b1116","banner":"#3b2530","ink":"#f9ebef","accent":"#e4a0ae"},"ocean":{"id":"ocean","paper":"#101d2a","side":"#0b1520","banner":"#20374b","ink":"#edf7fb","accent":"#78d0cb"},"graphite":{"id":"graphite","paper":"#1d2022","side":"#15181a","banner":"#303638","ink":"#f2f5f3","accent":"#9ad9c1"},"copper":{"id":"copper","paper":"#221d1a","side":"#181411","banner":"#382d25","ink":"#f8f0e9","accent":"#d8a174"},"abyss":{"id":"abyss","paper":"#0a0e13","side":"#070a0e","banner":"#17202b","ink":"#e9f1f7","accent":"#79a9d2"},"blackout":{"id":"blackout","paper":"#090909","side":"#050505","banner":"#1b1b1b","ink":"#f2f2f2","accent":"#a9adb5"},"eclipse":{"id":"eclipse","paper":"#11100e","side":"#0b0a09","banner":"#262219","ink":"#f6f0e5","accent":"#c8a66b"},"noir":{"id":"noir","paper":"#0e0e10","side":"#08080a","banner":"#222025","ink":"#f2eef0","accent":"#d77b85"},"deep-space":{"id":"deep-space","paper":"#0c0c18","side":"#070711","banner":"#1c1b30","ink":"#eeecfa","accent":"#9b96d6"},"evergreen":{"id":"evergreen","paper":"#0b1512","side":"#07100d","banner":"#1c2b25","ink":"#ecf6ef","accent":"#87bca4"}};
const query=new URLSearchParams(location.search);
const selected=themePalette[query.get('theme')]||themePalette.paper;
const requestedAccent=query.get('accent');
const accent=/^#[0-9a-fA-F]{6}$/.test(requestedAccent||'')?requestedAccent:selected.accent;
const root=document.documentElement;
root.style.setProperty('--paper',selected.paper);
root.style.setProperty('--ink',selected.ink);
root.style.setProperty('--side',selected.side);
root.style.setProperty('--banner',selected.banner);
root.style.setProperty('--accent',accent);
root.style.setProperty('--line',`color-mix(in srgb, ${selected.ink} 18%, transparent)`);
root.style.setProperty('--muted',`color-mix(in srgb, ${selected.ink} 78%, ${selected.paper})`);
root.dataset.theme=selected.id;
